  font-size: 13px;
  font-weight: 600;
  pointer-events: none;
}

.markers { position: absolute; inset: 0; pointer-events: none; }

.marker {
  position: absolute;
  width: 56px;
  height: 56px;
  margin: -28px 0 0 -28px;
  border: 4px solid #7be495;
  border-radius: 50%;
  box-shadow: 0 0 0 3px rgba(123, 228, 149, 0.35), 0 0 14px rgba(123, 228, 149, 0.6);
  animation: pop 0.35s ease-out;
}

.marker::after {
  content: "✓";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  font-weight: 800;
  color: #7be495;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7);
}

@keyframes pop {
  from { transform: scale(0.4); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.marker.hint-ring {
  border-color: #ffd166;
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.4), 0 0 18px rgba(255, 209, 102, 0.8);
  animation: pulse 0.7s ease-in-out infinite alternate;
}

@keyframes pulse {
  from { transform: scale(1); opacity: 1; }
  to { transform: scale(1.18); opacity: 0.75; }
}

.miss {
  position: absolute;
  width: 34px;
  height: 34px;
  margin: -17px 0 0 -17px;
  color: #ff6b5e;
  font-size: 30px;
  font-weight: 800;
  text-align: center;
  line-height: 34px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
  animation: fadeout 0.7s ease-out forwards;
}

@keyframes fadeout {
  from { opacity: 1; }
  to { opacity: 0; }
}

#boards.shake { animation: shake 0.3s; }

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}

